function avatar(array $u):string{
 $path=(string)($u['avatar_path']??'');
 return $path&&local_image_file($path)?'<img class="avatar" src="'.e($path).'" alt="Profile photo of '.e($u['name']).'">':'<img class="avatar default-avatar" src="assets/design/default-avatar.svg" alt="Default profile picture for '.e($u['name']).'">';
}
/** Style and script files get a short fingerprint in their file name (theme-1a2b3c4d5e.css), so a CDN that
    ignores "?v=" can never serve an old copy. The copy is made automatically the first time it is needed. */
function asset_url(string $f):string{static $c=[];if(isset($c[$f]))return $c[$f];
 $dir=__DIR__.'/../public/assets/';$src=$dir.$f;if(!is_file($src))return $c[$f]='assets/'.$f;
 $i=pathinfo($f);$h=substr(md5(filemtime($src).'-'.filesize($src)),0,10);$name=$i['filename'].'-'.$h.'.'.$i['extension'];
 if(!is_file($dir.$name)){$tmp=$dir.$name.'.'.getmypid().'.tmp';
  if(!@copy($src,$tmp)||!@rename($tmp,$dir.$name)){@unlink($tmp);return $c[$f]='assets/'.$f.'?v='.$h;}
  foreach(glob($dir.$i['filename'].'-*.'.$i['extension'])?:[] as $old)if(basename($old)!==$name&&preg_match('~^'.preg_quote($i['filename'],'~').'-[0-9a-f]{10}\.'.$i['extension'].'$~',basename($old))&&filemtime($old)<time()-86400)@unlink($old);}
 return $c[$f]='assets/'.$name;}
/** The automatic tour is offered once per account (kept on the server, so it does not return after signing in again). */
function tour_seen(int $uid):bool{try{return (bool)val('SELECT 1 FROM settings WHERE setting_key=?',['tour_seen_'.$uid]);}catch(Throwable $e){return false;}}
function mode_button(string $cls=''):string{return '<button type="button" class="mode-btn '.$cls.'" data-mode-toggle aria-pressed="false" aria-label="Switch to dark mode" title="Dark mode"><svg class="mode-moon" viewBox="0 0 24 24" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg><svg class="mode-sun" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg></button>';}
function mode_card():string{$o=fn($m,$t,$d)=>'<button type="button" class="mode-opt" role="radio" aria-checked="false" data-mode-set="'.$m.'"><b>'.$t.'</b><small>'.$d.'</small></button>';
 return '<section class="card mode-card"><h2>How BULIG looks</h2><p class="muted">Choose light or dark colours. Auto follows your phone or computer setting. Saved on this device.</p><div class="mode-opts" role="radiogroup" aria-label="How BULIG looks">'.$o('light','Light','Bright and clear').$o('dark','Dark','Easy on the eyes at night').$o('auto','Auto','Follows this device').'</div></section>';}
/* Loading screens: the BULIG opening screen (first page of a visit), and a hello from the person's own
   character right after signing in. Both show only while the page loads (loading.js hides them). */
function loading_screens(?array $cu,string $class):string{
 $h='<div class="boot" aria-hidden="true"><span class="boot-glow"></span><span class="boot-l l1">a</span><span class="boot-l l2">b</span><span class="boot-l l3">ma</span><span class="boot-l l4">E</span><span class="boot-logo"></span><span class="boot-bar"><i></i></span><span class="boot-hills"></span><span class="boot-kid k1"></span><span class="boot-kid k2"></span></div>';
 if($cu&&!empty($_SESSION['hello'])&&($_GET['page']??'dashboard')==='dashboard'&&!($cu['role']==='admin'&&!empty($_SESSION['pin_pending']))){unset($_SESSION['hello']);
  $first=explode(' ',trim((string)$cu['name']))[0];$hr=(int)date('G');$greet=$hr<12?'GOOD MORNING':($hr<18?'GOOD AFTERNOON':'GOOD EVENING');
  $who=$cu['role']==='pupil'?(pf_is_girl()?'girl':'boy'):($cu['role']==='admin'?'admin-':'teacher-').(tf_is_male((int)$cu['id'])?'male':'female');
  [$title,$text]=$cu['role']==='pupil'?['Hi, '.$first.'!','Getting your lessons ready…']:($cu['role']==='teacher'?['Hi, Teacher '.$first.'!','Opening your class…']:['Welcome back, '.$first.'!','Checking the whole school…']);
  $h.='<div class="hello hello-'.e($cu['role']).'" data-hello role="status" aria-live="polite"><span class="hello-sun"></span><span class="hello-ring"></span><div class="hello-in"><img class="hello-who" src="'.char_src($who).'" alt=""><div class="hello-txt"><small>'.($cu['role']==='admin'?'ADMINISTRATOR':$greet).'</small><b>'.e($title).'</b><span>'.e($text).'</span><span class="hello-bar"><i></i></span></div></div></div>';}
 return $h;
}
