s="font" type="font/woff2" crossorigin><link rel="stylesheet" href="'.asset_url('theme.css').'"><link rel="stylesheet" href="'.asset_url('dark.css').'"><script src="'.asset_url('mode.js').'"></script><script defer src="'.asset_url('app.js').'"></script><script defer src="'.asset_url('offline.js').'"></script><script defer src="'.asset_url('tour.js').'"></script><script defer src="'.asset_url('quick.js').'"></script><script defer src="'.asset_url('loading.js').'"></script><script defer src="'.asset_url('learn.js').'"></script><script defer src="'.asset_url('motion.js').'"></script><script defer src="'.asset_url('delight.js').'"></script><script defer src="'.asset_url('remind.js').'"></script><script defer src="'.asset_url('sfx.js').'"></script></head><body class="'.e($class).'">'.loading_screens($cu,$class).($cu&&$cu['role']==='pupil'&&pupil_grade((int)$cu['id'])<=2?'<span hidden data-kid-ui></span>':'');}
function foot():void{echo '</body></html>';}
