function shell(array $u,string $page):void{
 head(ucfirst(str_replace('_',' ',$page)),'workspace role-'.$u['role'].' view-'.preg_replace('/[^a-z_]/','',$page));$nav=$u['role']==='pupil'?['dashboard'=>['home','Overview'],'lessons'=>['book','My lessons'],'calendar'=>['cal','My calendar'],'achievements'=>['star','My achievements'],'profile'=>['user','My profile'],'settings'=>['settings','Settings']]:($u['role']==='teacher'?['dashboard'=>['home','Overview'],'class_demo'=>['book','Class Demo'],'manage'=>['people','My pupils'],'sections'=>['school','My sections'],'review'=>['check','Activity history'],'profile'=>['user','My profile']]:['dashboard'=>['home','Overview'],'accounts'=>['people','Teachers'],'reports'=>['chart','Reports'],'content'=>['book','Lesson studio'],'activity_log'=>['clock','Activity log'],'health'=>['heart','System health'],'settings'=>['settings','Settings'],'profile'=>['user','My profile']]);
 echo '<button type="button" class="mobile-menu-toggle" aria-controls="mobile-sidebar" aria-expanded="false" aria-label="Open navigation">'.icon('menu').' Menu</button><div class="sidebar-shade" hidden></div><aside class="sidebar" id="mobile-sidebar" aria-label="Main navigation"><button type="button" class="sidebar-close" aria-label="Close navigation">'.icon('close').'</button><a class="brand" href="?page=dashboard"><img src="assets/bulig-logo.png" alt="BULIG"></a><p class="navlabel">'.e($u['role']==='pupil'?'YOUR LEARNING SPACE':strtoupper($u['role']).' WORKSPACE').'</p><nav>';$navOn=$u['role']==='teacher'?(['accounts'=>'manage','cards'=>'manage','progress'=>'manage','certificates'=>'manage','guide'=>'class_demo'][$page]??$page):$page;foreach($nav as $key=>$v)echo '<a class="navitem '.($navOn===$key?'selected':'').'" href="?page='.$key.'"'.($navOn===$key?' aria-current="page"':'').'><span class="nav-ic">'.icon($v[0]).'</span><span class="nav-tx">'.e($v[1]).'</span></a>';
 echo '</nav><div class="sidebar-bottom"><div class="person">'.avatar($u).'<div><strong>'.e($u['name']).'</strong><small>'.e($u['public_id']).'</small></div></div>'.sidebar_chips($u).'<form method="post">'.csrf_field().'<input type="hidden" name="action" value="logout"><button class="signout">'.icon('logout').'Sign out</button></form></div></aside>'.($u['role']==='pupil'?pupil_tabbar($page):'').'<div class="mainwrap"><a class="mobile-brand" href="?page=dashboard" aria-label="BULIG home"><img src="assets/bulig-logo.png" alt="BULIG"></a>'.mode_button('mode-mobile'.($u['role']==='pupil'?' mode-pupil':'')).''.($u['role']==='pupil'?'<form method="post" class="mobile-signout">'.csrf_field().'<input type="hidden" name="action" value="logout"><button aria-label="Sign out">'.icon('logout').'<span>Sign out</span></button></form>':'').'<header class="topbar"><span>BUKIDNON’S UNIFIED LITERACY AND INTERVENTION GATEWAY</span>'.mode_button('mode-top').'<span class="rolepill">'.e(ucfirst($u['role'])).'</span></header><main class="main">'.saved_login_offer($u);notice();identity_banner($u,$page);
}
function shell_end():void{echo '</main><footer class="sitefooter">BULIG · Building Up Literacy, Inspiring Growth</footer></div>';foot();}
function source_link(int $n,int $lid=0):string{
 $level=$lid?lesson_level($lid):1;$grade=per_grade_level($level)?lesson_grade($lid):null;
 if(in_array($level,[2,3,4,5,6,7,8],true)){
  $meta=module_source_meta($level,$grade);
  if(!$meta||(current_user()['role']??'')==='pupil'&&!in_array($n,$meta['pupil_pages'],true))return '';
 }
 return '<a class="source-link" href="?page=source&amp;level='.$level.($grade?'&amp;grade='.$grade:'').'&amp;n='.$n.'" target="_blank" rel="noopener">'.icon('book').'Official '.e(module_label($level,$grade)).' · PDF page '.$n.'</a>';
}
/** "Level 4 · Grade 3" for per-grade modules, otherwise the level name. */
function module_label(int $level,?int $grade):string{return level_label($level).($grade?' · Grade '.$grade:'');}

function login_view():void{
 $role=in_array($_GET['role']??'',['pupil','teacher','admin'],true)?$_GET['role']:'pupil';$admin=$role==='admin';$confirmed=$admin&&($_GET['confirm']??'')==='1';head($admin?'Administrator access':'Welcome','login-page'.($admin?' admin-mode':''));
 echo ''.mode_button('mode-login').'<main class="login-layout"><section class="login-story">'.($admin?'':login_fx($role)).'<a class="login-brand" href="?page=login"><img src="assets/bulig-logo.png" alt="BULIG"></a><div class="story-content">'.($admin?'<span class="eyebrow">'.icon('shield').' ADMINISTRATOR WORKSPACE</span><h1>Handle with<br>care.</h1><p>This area manages teacher accounts, lessons and settings for every BULIG classroom.</p>':'<span class="eyebrow">A LITTLE PRACTICE. A LOT OF POSSIBILITY.</span><h1>Small steps.<br>Bright futures.</h1><p>A welcoming place to read, speak, and grow.<br>Your next adventure starts with a little practice.</p>').'<div class="story-photo"><img src="assets/images/covers/login.webp" alt="Happy pupils reading books together in a sunny meadow"><span>'.icon('book').'Level 1 · Oral Language</span></div></div><small>Building Up Literacy, Inspiring Growth</small></section><section class="login-panel"><div class="login-card">';notice();
 if($admin&&($pinUid=admin_pin_pending())){admin_pin_card($pinUid);echo '</div></section></main>';foot();return;}
 if($admin&&!empty($_SESSION['login_error'])){echo '<div class="pin-error" role="alert">'.icon('alert').'<span>'.e($_SESSION['login_error']).'</span></div>';unset($_SESSION['login_error']);}
 if($admin&&!$confirmed){echo '<div class="admin-warning" role="alertdialog" aria-labelledby="admin-warning-title" aria-describedby="admin-warning-text"><span class="admin-warning-icon">'.icon('alert').'</span><span class="eyebrow">RESTRICTED AREA</span><h2 id="admin-warning-title">Are you an<br>administrator?</h2><p id="admin-warning-text">This sign-in is only for BULIG administrators. Pupils and teachers never need this page.</p><ul class="admin-checklist"><li>'.icon('check').'I manage BULIG teacher accounts or lesson content.</li><li>'.icon('check').'I was given an administrator ID by the BULIG team.</li><li>'.icon('lock').'Failed sign-in attempts are recorded.</li></ul><div class="admin-actions"><a class="btn primary full" href="?page=login&amp;role=admin&amp;confirm=1">'.icon('shield').'Yes, I am an administrator</a><a class="btn secondary full" href="?page=login">'.icon('arrow','flip').'No, take me back</a></div></div></div></section></main>';foot();return;}
 if($admin){echo '<span class="admin-badge">'.icon('shield').'Admin mode</span><h2>Administrator<br>sign in.</h2><p class="muted">Use the administrator ID and password you were given.</p>';}else
 echo '<div class="login-top"><span class="eyebrow">WELCOME TO BULIG</span><a class="admin-pill" href="?page=login&amp;role=admin" title="For school administrators only">'.icon('shield').'Admin</a></div><h2>'.($role==='pupil'?'Your next adventure<br>starts here.':($role==='teacher'?'Welcome back,<br>teacher.':'Administrator<br>sign in.')).'</h2><p class="muted">'.($role==='pupil'?'A little practice. A little discovery. A brighter day.':'Sign in to your BULIG workspace.').'</p>';
 echo ($admin?'':'<nav class="role-tabs"><a class="'.($role==='pupil'?'active':'').'" href="?page=login&role=pupil">'.icon('user').'Pupil</a><a class="'.($role==='teacher'?'active':'').'" href="?page=login&role=teacher">'.icon('people').'Teacher</a></nav>').'<form method="post" class="stack">'.csrf_field().'<input type="hidden" name="action" value="login"><input type="hidden" name="role" value="'.$role.'"><label>'.ucfirst($role).' ID<input name="public_id" autocomplete="username" required maxlength="30" '.($role==='pupil'?'inputmode="numeric"':'').' placeholder="'.($role==='pupil'?'Enter your pupil ID':($role==='teacher'?'Enter your teacher ID':'Enter your admin ID')).'"'.($role==='pupil'&&preg_match('/^[A-Za-z0-9-]{1,30}$/',(string)($_GET['id']??''))?' value="'.e((string)$_GET['id']).'"':'').'></label><label>Password<span class="password-field"><input id="password" name="password" type="password" autocomplete="current-password" required'.($role==='pupil'&&preg_match('/^[A-Za-z0-9-]{1,30}$/',(string)($_GET['id']??''))?' autofocus':'').' maxlength="72" placeholder="Enter your password"><button type="button" class="show-password" data-password="password">Show</button></span></label><button class="btn primary full" type="submit">'.($admin?icon('shield').'Sign in as administrator':'Let’s go '.icon('arrow')).'</button></form><div class="login-help">'.icon('lock').'<span>'.($role==='pupil'?'Need help signing in? Ask your teacher.':'Need help signing in? Ask your administrator.').'</span></div>'.($admin?'<a class="admin-entry" href="?page=login">Not an administrator? Go back</a>':'').'</div></section></main>';foot();
}
/* Login effects: sunrise glow, hills, clouds, birds, floating letters and characters (v60) */
function login_fx(string $role):string{
 $cloud='<path d="M10 40a14 14 0 0 1 20-16 22 22 0 0 1 40-6 16 16 0 0 1 30 10 12 12 0 0 1 4 22H14a8 8 0 0 1-4-10z"/>';
 $bird='<path d="M1 7q6-6 12 0q6-6 12 0"/>';
 [$a,$b]=$role==='teacher'?[char_src('teacher-male','cheer'),char_src('teacher-female')]:[char_src('boy','cheer'),char_src('girl')];
 return '<div class="login-fx" aria-hidden="true"><span class="lfx-glow"></span>'
  .'<svg class="lfx-cloud lfx-c1" viewBox="0 0 120 50">'.$cloud.'</svg><svg class="lfx-cloud lfx-c2" viewBox="0 0 120 50">'.$cloud.'</svg>'
  .'<svg class="lfx-bird lfx-b1" viewBox="0 0 26 14">'.$bird.'</svg><svg class="lfx-bird lfx-b2" viewBox="0 0 26 14">'.$bird.'</svg>'
  .'<span class="lfx-letters" data-lfx-letters></span>'
  .'<svg class="lfx-hills" viewBox="0 0 400 80" preserveAspectRatio="none"><path d="M0 50q100-40 200-10t200-10v50H0z"/><path d="M0 64q120-24 220-4t180-6v26H0z"/></svg>'
  .'<span class="lfx-kids"><img class="lfx-kid lfx-k1" src="'.$a.'" alt=""><img class="lfx-kid lfx-k2" src="'.$b.'" alt=""></span></div>';
}
function pupil_dashboard(array $u):void{
 echo pf_defs();pupil_welcome($u);echo pupil_celebrations($u).class_done_note((int)$u['id']);
 $pid=(int)$u['id'];$s=progress_stats($pid);$assign=one('SELECT l.* FROM bulig_levels l JOIN pupil_level_assignments a ON a.level_id=l.id WHERE a.pupil_id=?',[$pid]);pupil_progress_cards($pid,$s,$assign);echo daily_goal_card($pid);pupil_next_step($pid);echo pf_helper($u);
