function pupil_lessons(array $u):void{
 $pid=(int)$u['id'];echo pf_defs().class_done_note($pid);$assign=one('SELECT l.* FROM bulig_levels l JOIN pupil_level_assignments a ON a.level_id=l.id WHERE a.pupil_id=?',[$pid]);$level=(int)($_GET['level']??0);
 if(!$level){level_cards($assign);return;}
 if(!level_available($pid,$level))fail('This level is not available yet. Complete your earlier level or ask your teacher about your starting level.',403);
 $skipped=$assign&&(int)$assign['id']>$level;
 if($skipped)echo '<section class="notice"><strong>Skipped · optional practice</strong><p>Your teacher chose a later starting level. You can explore any lesson here whenever you want. This level is not required for your current learning path.</p></section>';
 $lessons=rows('SELECT l.*,p.completed_at,(SELECT COUNT(*) FROM activity_completion c JOIN activities a ON a.id=c.activity_id WHERE a.lesson_id=l.id AND c.pupil_id=p.pupil_id AND c.prompt_snapshot=?) inclass FROM lessons l JOIN modules m ON m.id=l.module_id LEFT JOIN pupil_progress p ON p.lesson_id=l.id AND p.pupil_id=? WHERE m.level_id=? AND l.published=1'.GRADE_SQL.' ORDER BY l.position',[CLASS_DONE_MARK,$pid,$level,pupil_grade($pid)]);
 $done=count(array_filter($lessons,fn($l)=>(bool)$l['completed_at']));$total=count($lessons);$current=null;foreach($lessons as $l)if(!$l['completed_at']){$current=$l;break;}
 echo '<a class="btn secondary back-levels" href="?page=lessons">'.icon('arrow').'Back to all levels</a><section class="journey" id="level'.$level.'-path"><div class="level-banner"><div><span class="eyebrow">'.e(level_label($level)).'</span><h2>'.($level===1?'Find your voice.':($level===4?'Read words with confidence.':($level===5?'Read stories smoothly.':($level===6?'Listen well. Learn new words.':($level===7?'Read, think and understand.':($level===8?'Fall in love with reading.':'Discover the sounds in words.')))))).'</h2><p>'.e(lesson_count_label($level,$total)).' · '.$done.' complete</p></div><span class="banner-icon">'.icon('book').'</span></div><div class="journey-head"><strong>Your learning path</strong><span>'.round($done/max(1,$total)*100).'% complete</span></div><progress max="'.$total.'" value="'.$done.'" aria-label="Completed lessons and assessments"></progress>'.pf_map_open($level,$lessons,$pid,$current).'<div class="lesson-path">';
 foreach($lessons as $l){$available=lesson_available($pid,(int)$l['id']);$complete=(bool)$l['completed_at'];$active=$available&&!$complete&&$current&&$current['id']===$l['id'];echo '<div class="path-row '.($complete?'done':($active?'current':($available?'available':'locked'))).'"><div class="path-node">'.icon($complete?'check':($available?'book':'lock')).'</div><div class="path-copy"><span class="eyebrow">'.e(lesson_display_label($level,(int)$l['position'])).($skipped?' · OPTIONAL PRACTICE':($active?' · YOU ARE HERE':'')).'</span><h3>'.e($l['subtitle']).'</h3><p>'.e($l['title']).'</p></div>'.($available?'<a class="btn '.($active?'primary':'quiet').'" href="?page=lesson&id='.$l['id'].'">'.($complete?'Review':'Continue').icon('arrow').'</a>':'<span class="lockedlabel">Locked</span>').'</div>';}
 echo '</div></div></section>';if(!$current)echo '<section class="card"><h2>You completed '.e(level_label($level)).'!</h2><p>Explore your next available level, or revisit your saved work.</p><a class="btn primary" href="?page=lessons">See my levels '.icon('arrow').'</a></section>';
}

function lesson_view(array $u):void{
 $pid=(int)$u['id'];$lid=(int)($_GET['id']??1);$off=offline_view($pid,$lid);if(!$off&&!lesson_available($pid,$lid))fail('This lesson is not available yet.',403);$lesson=one('SELECT * FROM lessons WHERE id=?',[$lid]);$all=activities($lid,$pid);$aid=(int)($_GET['activity']??0);$chosen=null;
 if($aid){if(!$off)allowed_activity($pid,$aid);foreach($all as $item)if((int)$item['id']===$aid)$chosen=$item;if(!$chosen)fail('Activity does not belong to this lesson.',404);}else $chosen=next_activity($pid,$lid);
 $done=count(array_filter($all,fn($a)=>completion_ok($a)));$finished=(bool)val('SELECT completed_at FROM pupil_progress WHERE pupil_id=? AND lesson_id=?',[$pid,$lid]);
 head(level_label(lesson_level($lid)).' · '.$lesson['subtitle'],'activity-page');echo '<header class="activity-header"><a class="iconbutton" href="?page=lessons&amp;level='.lesson_level($lid).'#level'.lesson_level($lid).'-path" aria-label="Back to my lessons">'.icon('close').'</a><div><strong>'.e(level_label(lesson_level($lid)).' · '.$lesson['subtitle']).'</strong><span>'.e($lesson['title']).'</span></div><div class="activity-progress"><span>'.$done.' / '.count($all).' complete</span><progress max="'.count($all).'" value="'.$done.'"></progress></div></header><main class="activity-main">';notice();
 if(!$chosen){
  $xp=(int)val('SELECT COALESCE(SUM(x.amount),0) FROM xp_transactions x JOIN activities a ON a.id=x.activity_id WHERE x.pupil_id=? AND a.lesson_id=?',[$pid,$lid]);
  echo pf_defs().'<section class="completion-card pf-completion">'.pf_lesson_celebration($lid,$pid,$finished).'<span class="eyebrow">'.e(lesson_display_label(lesson_level($lid),(int)$lesson['position'])).'</span><h1>'.($finished?'Lesson complete!':'You did it!').'</h1><p>You earned <strong>'.$xp.' XP</strong> and gave your voice a little more practice.</p>';
  if($finished)echo '<a class="btn primary" href="?page=lessons&amp;level='.lesson_level($lid).'#level'.lesson_level($lid).'-path">Back to my lessons '.icon('arrow').'</a>';
  else echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="finish_lesson"><input type="hidden" name="lesson_id" value="'.$lid.'"><button class="btn primary next">Done '.icon('check').'</button></form>';
  echo '</section>';if($finished&&isset($_GET['finished']))echo pupil_celebrations($u);
 }else{
  $a=$chosen;$native=level2_card_set($a);$mode=$a['response_mode'];$question=one('SELECT * FROM questions WHERE activity_id=?',[$a['id']]);$exact=$question&&$question['grading']==='exact';if($exact||($mode==='drawing'&&!draw_allowed($a)))$mode='answer';$readonly=completion_ok($a);
  $draft=one('SELECT * FROM activity_drafts WHERE pupil_id=? AND activity_id=?',[$pid,$a['id']]);$response=$draft['response']??$a['response']??'';$drawing=$draft['drawing']??$a['drawing']??'';$transcript=$draft['transcript']??'';$imgs=activity_images($a);$worksheet=false;
  echo '<div class="activity-meta"><span class="eyebrow">'.e(lesson_display_label(lesson_level($lid),(int)$lesson['position'])).' · '.e(['pre'=>'BEFORE WE BEGIN','learn'=>'LET’S PRACTICE','post'=>'SHOW WHAT YOU LEARNED'][$a['phase']]).'</span><span class="xpchip">'.icon('bolt').(int)$a['xp_reward'].' XP</span></div>';
  narration_controls($native?$native['cards'][0]['narration']:$a['narration']);echo '<h1 class="activity-title">'.e($native['title']??$a['title']).'</h1><p class="activity-instruction">'.e($native?($mode==='none'?'Look at each card and listen.':'Look at each card, listen, and share your answer.'):str_replace('Draw your answer, or describe your paper drawing.',$mode==='drawing'?'Draw it here, or draw on paper and upload a photo.':'Draw on paper if you like, then tell about your drawing here.',(string)$a['instructions'])).'</p>';
  $passage=$native?null:level4_passage($a);$sheet=null;
  if(!$native&&$passage===null&&$sheet===null)render_activity_visuals($a);

  if($a['feedback'])echo '<div class="feedback"><div><strong>A note from your teacher</strong><p>'.e($a['feedback']).'</p></div></div>';
  echo '<form method="post" id="activity-form" class="activity-form" data-mode="'.e($mode).'" data-draft="'.($readonly?'off':'on').'">'.csrf_field().'<input type="hidden" name="action" value="submit"><input type="hidden" name="activity_id" value="'.$a['id'].'"><input type="hidden" name="transcript" id="transcript" value="'.e($transcript).'"><input type="hidden" name="drawing" id="drawing-data" value="'.e($drawing).'"><input type="hidden" id="expected-text" value="'.e($a['expected_text']??'').'">';
  if($native)render_level2_pupil($native,$response,$readonly,$mode);
  elseif($mode==='answer'&&$a['type']==='sentence')echo '<div class="answer-card sentence-card"><label for="response">'.e($a['prompt']).'</label><input id="response" name="response" value="'.e($response).'" maxlength="12000" placeholder="Your answer" autocomplete="off" '.($readonly?'readonly':'required').'></div>';
  else{
   $grid=level3_reading_grid($a)??$passage??$sheet;echo '<div class="answer-card">'.($grid??'<div class="prompt '.(strlen($a['prompt'])>800?'longprompt':'').'">'.nl2br(e(lesson_level($lid)===6?level5_reflow($a['prompt']):$a['prompt'])).'</div>');
   if(in_array($mode,['answer','drawing'],true)){
    if($a['type']==='choice')foreach(rows('SELECT an.content FROM answers an JOIN questions q ON q.id=an.question_id WHERE q.activity_id=?',[$a['id']]) as $op)echo '<label class="answer-option"><input type="radio" name="response" value="'.e($op['content']).'" '.($response===$op['content']?'checked':'').' '.($readonly?'disabled':'required').'>'.e($op['content']).'</label>';
    else{if($passage!==null&&!$readonly)echo '<div class="fluency-timer" id="fluency-timer" data-words="'.level4_passage_parts($a)['words'].'"><button type="button" class="btn primary" id="fluency-start">'.icon('mic').'Start reading</button><button type="button" class="btn secondary" id="fluency-stop" hidden>'.icon('check').'I’m done</button><output id="fluency-clock" aria-live="polite">0:00</output><span id="fluency-status" role="status">Tap Start reading, then read the whole passage aloud.</span></div><p class="speech-note">The microphone may mishear. Your teacher listens and counts the miscues.</p><div id="word-feedback" aria-live="polite"></div>';echo '<label class="response-label" for="response">'.($worksheet?'Your numbered answers (or mark the sheet below)':($mode==='drawing'?'Tell us about your drawing (optional)':($passage!==null?'Your reading (the microphone writes what it hears; your time is added when you finish)':'Your answer'))).'</label><textarea id="response" name="response" rows="3" maxlength="12000" placeholder="'.($passage!==null?'What you read appears here…':'Type here, or tap Speak Answer…').'" '.($readonly?'readonly':($mode==='answer'?'required':'')).'>'.e($response).'</textarea>';}
   }echo '</div>';
  }
  if($mode==='drawing'&&!$native){$photo=str_starts_with($drawing,'data:image/jpeg');
   echo '<div class="draw-choice" role="group" aria-label="How do you want to answer?"><button type="button" class="dc-tab'.($photo?'':' on').'" data-dc="draw" aria-pressed="'.($photo?'false':'true').'">'.icon('edit').'Draw it</button><button type="button" class="dc-tab'.($photo?' on':'').'" data-dc="photo" aria-pressed="'.($photo?'true':'false').'">'.icon('camera').'Upload a photo</button></div>';
   echo '<div class="drawing-panel"'.($photo?' hidden':'').'><div class="drawing-toolbar"><strong>Your drawing</strong><label>Color <input type="color" id="pen-color" value="#217c4b"></label><button class="btn quiet" type="button" id="clear-drawing">Clear my marks</button></div><div class="worksheet-scroll"><div class="worksheet-surface"><canvas id="drawing-canvas" width="900" height="500" aria-label="Drawing area; you may also answer in text"></canvas></div></div></div>';
   echo '<div class="photo-panel"'.($photo?'':' hidden').'><div class="pp-empty"'.($photo?' hidden':'').'><span class="pp-ic">'.icon('image').'</span><p>Draw on paper, then take a clear photo of it. Hold the phone straight above the paper.</p>'.($readonly?'':'<label class="btn primary pp-btn">'.icon('camera').'Take a photo<input type="file" accept="image/*" capture="environment" class="pp-input"></label><label class="btn secondary pp-btn">'.icon('image').'Choose from gallery<input type="file" accept="image/*" class="pp-input"></label>').'</div><div class="pp-done"'.($photo?'':' hidden').'><div class="pp-photo"><img class="pp-img" src="'.($photo?e($drawing):'').'" alt="Photo of your paper drawing"><span class="pp-ok">'.icon('check').'Photo added</span></div>'.($readonly?'':'<div class="pp-mini"><label class="btn secondary">'.icon('camera').'Retake<input type="file" accept="image/*" capture="environment" class="pp-input"></label><label class="btn secondary">'.icon('image').'Change<input type="file" accept="image/*" class="pp-input"></label></div>').'</div><p class="pp-status" role="status"></p></div>';
  }
  if($native&&$drawing){echo '<details class="legacy-drawing"><summary>Previously saved worksheet drawing</summary><div class="review-worksheet">';$old='assets/images/level'.(lesson_level($lid)===2?'2a':'2b').'/page-'.sprintf('%03d',(int)$a['source_page']).'.webp';if(local_image_file($old))echo '<img class="review-sheet" src="'.e($old).'" alt="Original background for your earlier saved drawing">';echo '<img class="submitted-drawing" src="'.e($drawing).'" alt="Previously saved drawing"></div></details>';}
  if(!$readonly&&in_array($mode,['answer','drawing'],true)&&$a['type']!=='choice'&&$passage===null)echo '<div class="speak-row"><button type="button" class="btn secondary" id="recognize">'.icon('mic').'Speak Answer</button><button type="button" class="btn quiet" id="type-answer">'.icon('edit').'Type Answer</button><span id="speech-status" role="status">Choose either way to answer.</span></div><p class="speech-note">The microphone may mishear. Check the detected text before submitting.</p><div id="word-feedback" aria-live="polite"></div>';
  echo '<div id="answer-feedback" role="status" aria-live="polite" class="answer-feedback '.($readonly?'success':'').'">'.($readonly?icon('check').'<div><strong>'.($exact?'Correct!':'Saved. Well done!').'</strong><p>Your progress is saved. You can continue.</p></div>':'').'</div><div class="activity-bottom"><div><span id="draft-status" role="status">'.($draft?'Draft restored':($mode==='none'?'No answer needed on this page.':'Your work saves automatically.')).'</span>'.source_link((int)$a['source_page'],(int)$a['lesson_id']).'</div>';
  if(!$readonly)echo '<button id="submit-answer" class="btn primary next" type="submit">'.($mode==='none'?'Next':($mode==='perform'?'Done':($exact?'Check Answer':($native?'Submit activity':'Submit Answer')))).' '.icon($mode==='perform'?'check':'arrow').'</button>';
  echo '<a id="next-activity" class="btn primary next" href="?page=lesson&id='.$lid.'" '.(!$readonly?'hidden':'').'>'.($done===count($all)?'Finish Lesson':'Next').' '.icon('arrow').'</a></div></form>';
 }
 echo '<details class="lesson-outline"><summary>Lesson activities and saved work</summary>';foreach($all as $a){$enabled=completion_ok($a);echo '<div>'.($enabled?'<a href="?page=lesson&id='.$lid.'&activity='.$a['id'].'">':'<span>').e(ucfirst($a['phase']).' · '.$a['title']).($enabled?'</a>':'</span>').'<span class="status '.e($a['status']??'').'">'.($enabled?'Complete':($a['status']==='retry'?'Try again':'Not started')).'</span></div>';}echo '</details></main>';foot();
}
function teacher_dashboard(array $u):void{
 echo tf_defs().teacher_welcome($u);teacher_announcements();
 [$grade,$sid]=teacher_class_selection($u);
 $pupils=rows('SELECT u.*,p.grade_level,p.section,l.title level_title,a.level_id FROM users u JOIN pupils p ON p.user_id=u.id JOIN teacher_pupils t ON t.pupil_id=u.id JOIN pupil_level_assignments a ON a.pupil_id=u.id JOIN bulig_levels l ON l.id=a.level_id WHERE t.teacher_id=? AND p.grade_level=? AND (?=0 OR u.id IN(SELECT pupil_id FROM pupil_sections WHERE section_id=?)) ORDER BY u.name',[$u['id'],$grade,$sid,$sid]);$pending=(int)val("SELECT COUNT(*) FROM activity_completion c JOIN teacher_pupils t ON t.pupil_id=c.pupil_id JOIN pupils p ON p.user_id=c.pupil_id WHERE t.teacher_id=? AND p.grade_level=? AND (?=0 OR c.pupil_id IN(SELECT pupil_id FROM pupil_sections WHERE section_id=?)) AND c.status IN ('completed','approved')",[$u['id'],$grade,$sid,$sid]);
 $ids=array_map(fn($p)=>(int)$p['id'],$pupils);$stats=[];foreach($pupils as $p)$stats[(int)$p['id']]=progress_stats((int)$p['id']);
 $need=array_values(array_filter($pupils,fn($p)=>tf_needs_checkin($p,$stats[(int)$p['id']])));
 $badgeWeek=$ids?array_flip(array_map('intval',array_column(rows('SELECT DISTINCT pupil_id FROM pupil_badges WHERE pupil_id IN('.tf_in($ids).') AND earned_at>=?',[date('Y-m-d H:i:s',strtotime('-7 days'))]),'pupil_id'))):[];
 echo '<div class="tdash-head"><div><span class="eyebrow">TEACHER OVERVIEW</span><h1>Every learner matters.</h1><p class="muted">A clear view of your pupils’ next steps.</p></div><div class="tdash-actions"><a class="btn secondary" href="?page=class_demo">'.icon('book').'Class Demo</a><a class="btn primary" href="?page=accounts">'.icon('people').'Add a pupil</a></div></div>';
 section_filter($u,'dashboard',$sid,$grade);
 echo tf_checkin($need).tf_stats($ids,$pending,(int)val('SELECT COUNT(*) FROM lessons WHERE published=1'));
 if($pupils)echo tf_chart($ids).'<div class="tf-grid">'.tf_tree($pupils,$stats,$badgeWeek).tf_feed($ids).'</div>';
 echo '<section class="card tdash-table tf-table"><div class="section-heading"><h2>Class overview</h2><a href="?page=review">Activity history '.icon('arrow').'</a></div><div class="tablewrap"><table class="pupil-table"><thead><tr><th>Pupil</th><th>Section</th><th>Starting level</th><th>Completed</th><th>XP</th><th>Last learning day</th><th>Status</th></tr></thead><tbody>';
 foreach($pupils as $p){$s=$stats[(int)$p['id']];$inactive=!$s['last_activity_date']||$s['last_activity_date']<date('Y-m-d',strtotime('-7 days'));[$label,$tone]=!$p['active']?['Inactive account','off']:($inactive?['Needs a check-in','warn']:['Learning','ok']);
  echo '<tr><td data-label="Pupil"><a class="pupil-cell" href="?page=pupil&amp;id='.$p['id'].'">'.avatar($p).'<span><strong>'.e($p['name']).'</strong><small>'.e($p['public_id']).'</small></span></a></td><td data-label="Section">'.e($p['section']?:'—').'</td><td data-label="Starting level">'.e($p['level_title']).tf_progress((int)$p['id'],(int)$p['level_id'],$tone==='warn').'</td><td data-label="Completed"><strong>'.$s['completed'].'</strong> <small class="inline">activities</small></td><td data-label="XP"><strong>'.$s['xp'].'</strong><small>'.$s['current_streak'].'-day streak · best '.$s['longest_streak'].'</small></td><td data-label="Last learning day">'.e($s['last_activity_date']??'Not yet').'</td><td data-label="Status"><span class="status status-'.$tone.'">'.$label.'</span></td></tr>';}
 if(!$pupils)echo '<tr class="empty-row"><td colspan="7">No pupils in this selection yet. Choose another section or add a pupil.</td></tr>';echo '</tbody></table></div></section>';
}
