function accounts_view(array $u):void{
 if($u['role']==='admin'){admin_teachers_view($u);return;}
 $isAdmin=$u['role']==='admin';$people=$isAdmin?rows("SELECT * FROM users WHERE role='teacher' ORDER BY created_at DESC"):rows('SELECT u.*,p.grade_level,p.section,a.level_id,ps.section_id,pd.sex,pd.lrn FROM users u JOIN pupils p ON p.user_id=u.id JOIN teacher_pupils t ON t.pupil_id=u.id JOIN pupil_level_assignments a ON a.pupil_id=u.id LEFT JOIN pupil_sections ps ON ps.pupil_id=u.id LEFT JOIN pupil_details pd ON pd.pupil_id=u.id WHERE t.teacher_id=? ORDER BY u.created_at DESC',[$u['id']]);$levels=$isAdmin?[]:teacher_sections((int)$u['id']);
 echo pupils_tabs('accounts',count($people)).'<section class="card"><h2>Create a '.($isAdmin?'teacher':'pupil').' account</h2><form class="formgrid" method="post">'.csrf_field().'<input type="hidden" name="action" value="create_account"><label>Full name<input name="name" required maxlength="150"></label>';if($isAdmin)echo '<label>Password<input name="password" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label>';else echo '<div class="default-password"><strong>Default pupil password</strong><p>12345678</p><small>The pupil may keep it or change it in My profile.</small></div>';
 if(!$isAdmin)echo grade_fields([], $levels);echo '<div class="formend"><small>A unique '.($isAdmin?'Teacher':'Pupil').' ID is generated automatically.</small><button class="btn primary" type="submit">Create account '.icon('arrow').'</button></div></form></section>';if(!$isAdmin)import_card($u);echo '<section class="card"><div class="section-heading acc-head"><h2>'.count($people).' '.($isAdmin?'teachers':'pupils').'</h2>'.(!$isAdmin&&$people?'<a class="btn secondary" href="?page=cards">'.icon('id').'Print sign-in cards</a>':'').'</div>';
 foreach($people as $p){echo '<details class="account-detail"><summary>'.avatar($p).'<span><strong>'.e($p['name']).'</strong><small>'.e($p['public_id']).'</small></span><span class="status">'.($p['active']?'Active':'Inactive').'</span></summary><form method="post" class="formgrid">'.csrf_field().'<input type="hidden" name="action" value="update_account"><input type="hidden" name="id" value="'.$p['id'].'"><label>Full name<input name="name" value="'.e($p['name']).'" required maxlength="150"></label><label>New password (optional)<input name="password" type="password" minlength="8" maxlength="72" autocomplete="new-password"></label>';if(!$isAdmin)echo grade_fields($p,$levels);echo '<label class="checkbox"><input type="checkbox" name="active" '.($p['active']?'checked':'').'>Account active</label><button class="btn primary" type="submit">Save changes</button></form></details>';}
 echo '</section>';
}
function grade_fields(array $p,array $sections):string{
 $s='<label>Section<select name="section_id" required><option value="">Choose a section</option>';foreach($sections as $section)$s.='<option value="'.$section['id'].'" '.(($p['section_id']??0)==$section['id']?'selected':'').'>Grade '.$section['grade_level'].' · '.e($section['name']).'</option>';
 $s.='</select></label>'; $s.=pupil_details_fields($p); $s.=starting_level_field((int)($p['level_id']??1));
 return $s.'<div class="section-help"><a href="?page=sections">Add or edit your sections</a><p class="muted">Grade follows the section. Starting level is chosen separately: any Grade 1–6 pupil can start at any level. Future content stays locked.</p></div>';
}
function review_view(array $u):void{
 /* A short to-do list: one line per answer, "Needs feedback" first, a pupil filter, and one-tap feedback phrases. */
 $tab=in_array($_GET['tab']??'',['todo','done','all'],true)?$_GET['tab']:'todo';$fp=(int)($_GET['pupil']??0);$pg=max(1,(int)($_GET['p']??1));$per=30;
 $mine=rows('SELECT u.id,u.name FROM users u JOIN teacher_pupils t ON t.pupil_id=u.id WHERE t.teacher_id=? ORDER BY u.name',[$u['id']]);if($fp&&!in_array($fp,array_map('intval',array_column($mine,'id')),true))$fp=0;
 $pw=$fp?' AND c.pupil_id='.$fp:'';$back='?page=review&tab='.$tab.($fp?'&pupil='.$fp:'');echo tf_feedback_toast();
