 $base="FROM activity_completion c JOIN activities a ON a.id=c.activity_id JOIN lessons l ON l.id=a.lesson_id JOIN teacher_pupils t ON t.pupil_id=c.pupil_id JOIN users u ON u.id=c.pupil_id WHERE t.teacher_id=? AND c.status IN ('completed','approved')".$pw;
 $todoN=(int)val("SELECT COUNT(*) ".$base." AND c.reviewed_at IS NULL",[$u['id']])+count($ready);$doneN=(int)val("SELECT COUNT(*) ".$base." AND c.reviewed_at IS NOT NULL",[$u['id']]);
