 $list=rows("SELECT c.*,(SELECT 1 FROM audit_log al WHERE al.actor_id=c.pupil_id AND al.action='offline_answer' AND al.details=CONCAT('activity ',c.activity_id,' at ',c.submitted_at) LIMIT 1) answered_offline,a.lesson_id,a.image_path,a.title,a.source_page,a.type,l.subtitle,u.name,u.public_id ".$base.$cond." ORDER BY c.submitted_at DESC,c.id DESC LIMIT ".$per." OFFSET ".(($pg-1)*$per),[$u['id']]);
 echo '<div class="pageheading"><div><span class="eyebrow">TEACHER REVIEW</span><h1>A little feedback goes a long way.</h1><p class="muted">Open an answer to read it and leave a short note. Feedback is optional. Pupils can keep learning while they wait.</p></div></div>';
