 echo '<form method="get" class="rv-filter"><input type="hidden" name="page" value="review"><input type="hidden" name="tab" value="'.e($tab).'"><label><span class="sr-only">Pupil</span><select name="pupil" data-autosubmit><option value="0">All pupils</option>';foreach($mine as $m)echo '<option value="'.(int)$m['id'].'" '.($fp===(int)$m['id']?'selected':'').'>'.e($m['name']).'</option>';echo '</select></label><noscript><button class="btn quiet">Show</button></noscript></form></div>';
 $ini=function(string $n):string{$w=preg_split('/\s+/',trim($n));return strtoupper(mb_substr($w[0]??'',0,1).mb_substr($w[count($w)-1]??'',0,count($w)>1?1:0));};
 $phrases=['Great job!','Well done, keep it up!','Good try! Let’s read it again together.','I love your answer!','Please answer in a full sentence next time.','Check your spelling.','Speak a little louder next time.'];
