 $items=0;
 if($tab!=='done'&&$ready)echo '<details class="rv-group"><summary><span class="rv-group-ic">'.icon('chart').'</span><span class="rv-main"><strong>Assessments ready for optional scoring</strong><small>Rate them with the module rubric when you have time. Pupils are not waiting on these.</small></span><span class="rv-count">'.count($ready).'</span></summary><div class="rv-group-in">';
