  $criteria=json_decode($r['rubric_criteria']??'[]',true)?:[];foreach($criteria as $i=>$c)echo '<label>'.e($c).'<select name="scores['.$i.']" required><option value="">Select rating from original rubric</option><option value="1">1 · Needs improvement</option><option value="2">2 · Satisfactory</option><option value="3">3 · Good</option><option value="4">4 · Excellent</option></select></label>';
  if(!$criteria)echo '<p class="muted">No number score is given for this assessment. Save to confirm it is complete.</p>';echo $chips().'<label>Feedback<textarea name="feedback" maxlength="3000" rows="3"></textarea></label><div class="buttonrow"><button class="btn primary">'.icon('check').'Save</button></div></form></div></details>';}
 if($tab!=='done'&&$ready)echo '</div></details>';
 foreach($list as $r){$items++;$done=$r['reviewed_at']!==null;
  echo '<details class="rv-item'.($done?' rv-done':'').'"><summary><span class="rv-av">'.e($ini($r['name'])).'</span><span class="rv-main"><strong>'.e($r['name'].' · '.$r['subtitle'].' · '.$r['title']).'</strong><small>'.e(level_label(lesson_level((int)$r['lesson_id'])).' · '.date('M j, g:i A',strtotime((string)$r['submitted_at']))).(!empty($r['answered_offline'])?' · Answered offline':'').'</small></span><span class="rv-go">'.($done?icon('check').'Reviewed':'Give feedback').'</span></summary><div class="rv-body">';
  echo '<details><summary>Prompt and original instructions</summary><p class="preserve">'.e($r['prompt_snapshot']).'</p>'.source_link((int)$r['source_page'],(int)$r['lesson_id']).'</details>'.(trim((string)$r['response'])!==''?'<blockquote>'.nl2br(e($r['response'])).'</blockquote>':'<p class="rv-noanswer">No written answer. This activity is for listening, reading aloud or doing'.($r['drawing']?'. See the drawing below.':' with the class.').'</p>');
  if($r['drawing']){echo '<div class="review-worksheet">';if(in_array(lesson_level((int)$r['lesson_id']),[2,3],true)&&local_image_file((string)$r['image_path']))echo '<img class="review-sheet" src="'.e($r['image_path']).'" alt="Original worksheet" loading="lazy">';echo (str_starts_with((string)$r['drawing'],'data:image/jpeg')?'<span class="rv-photo-tag">Photo of paper drawing</span>':'').'<img class="submitted-drawing" src="'.e($r['drawing']).'" alt="'.(str_starts_with((string)$r['drawing'],'data:image/jpeg')?'Photo of the pupil’s paper drawing':'Pupil’s drawing').'" loading="lazy"></div>';}
  $read=one('SELECT * FROM reading_assessments WHERE pupil_id=? AND activity_id=? ORDER BY id DESC LIMIT 1',[$r['pupil_id'],$r['activity_id']]);if($read)echo '<p>Recognized words: '.e($read['transcript']).'</p><p class="muted">Word match: '.e($read['word_match_percent']).'%. This measures recognized text, not pronunciation.</p>';
  echo '<form method="post" class="stack">'.csrf_field().'<input type="hidden" name="action" value="review"><input type="hidden" name="back" value="'.e($back).'"><input type="hidden" name="completion_id" value="'.$r['id'].'">'.$chips().'<label>'.($done?'Your feedback':'Helpful feedback').'<textarea name="feedback" maxlength="3000" rows="3" placeholder="Tell the pupil what went well or how to try again.">'.e((string)$r['feedback']).'</textarea></label><div class="buttonrow"><button class="btn primary">'.icon('check').($done?'Update feedback':'Save feedback').'</button></div></form></div></details>';}
