 $sec=(int)($_GET['section']??0);$secs=rows('SELECT id,name,grade_level FROM sections WHERE teacher_id=? AND archived_at IS NULL ORDER BY grade_level,name',[$u['id']]);if($sec&&!in_array($sec,array_map('intval',array_column($secs,'id')),true))$sec=0;
 $list=rows('SELECT u.id,u.name,u.public_id,u.password_hash,u.active,d.sex,s.name section,s.grade_level FROM users u JOIN teacher_pupils t ON t.pupil_id=u.id LEFT JOIN pupil_details d ON d.pupil_id=u.id LEFT JOIN sections s ON s.id=(SELECT ps.section_id FROM pupil_sections ps WHERE ps.pupil_id=u.id ORDER BY ps.section_id LIMIT 1) WHERE t.teacher_id=? AND u.active=1'.($sec?' AND EXISTS(SELECT 1 FROM pupil_sections ps2 WHERE ps2.pupil_id=u.id AND ps2.section_id='.$sec.')':'').' ORDER BY s.grade_level,s.name,u.name',[$u['id']]);
