 echo '<div class="lc-tools no-print card"><form method="get" class="lc-filter"><input type="hidden" name="page" value="cards"><label>Section<select name="section" data-autosubmit><option value="0">All my pupils</option>';foreach($secs as $x)echo '<option value="'.(int)$x['id'].'" '.($sec===(int)$x['id']?'selected':'').'>Grade '.(int)$x['grade_level'].' · '.e($x['name']).'</option>';echo '</select></label><noscript><button class="btn quiet">Show</button></noscript></form>';
