 /* Checking the first password is slow, so the answer is remembered until the password changes. */
 $memo=[];if($list)foreach(rows("SELECT setting_key,setting_value FROM settings WHERE setting_key IN (".implode(',',array_fill(0,count($list),'?')).")",array_map(fn($p)=>'cardpw_'.(int)$p['id'],$list)) as $m)$memo[$m['setting_key']]=$m['setting_value'];
 foreach($list as $p){$k='cardpw_'.(int)$p['id'];$sig=substr(sha1((string)$p['password_hash']),0,16);
