/* About BULIG: the people and tools behind the system. */
function about_card():string{
 /* A credit shows its logo when the file is in assets/images/credits/, otherwise a letter badge. */
 $who=[['deped-bukidnon','SD','Schools Division of Bukidnon','DepEd · creators of the BULIG program','g'],['carl','CM','Carl Benedict H. Miculob','Web app creator and developer','g'],['claude','C','Claude','AI assistant by Anthropic · design and coding help','o'],['chatgpt','G','ChatGPT','AI assistant by OpenAI · ideas and writing help','b']];
 $h='<section class="card about-card"><div class="ab-head"><img src="assets/bulig-logo.png" alt="BULIG" loading="lazy"><div><h2>About BULIG</h2><p class="muted">Bukidnon’s Unified Literacy and Intervention Gateway</p></div></div><h3 class="ab-sub">Credits</h3><div class="ab-list">';
 foreach($who as [$f,$i,$n,$r,$c]){$img='';foreach(['webp','png','jpg','svg'] as $x)if(is_file(__DIR__.'/../public/assets/images/credits/'.$f.'.'.$x)){$img='assets/images/credits/'.$f.'.'.$x;break;}
  $h.='<div class="ab-p'.($f==='deped-bukidnon'?' ab-org':'').'">'.($img?'<img class="ab-logo" src="'.e($img).'" alt="" loading="lazy">':'<span class="ab-av ab-'.$c.'" aria-hidden="true">'.$i.'</span>').'<div><b>'.e($n).'</b><small>'.e($r).'</small></div></div>';}
 return $h.'</div><p class="ab-foot">Lessons and pictures are from the official DepEd BULIG modules.</p></section>';
}
function teacher_class_selection(array $u):array{
 $sid=max(0,(int)($_GET['section_id']??0));$section=$sid?owned_section($sid,(int)$u['id']):null;
 $sections=teacher_sections((int)$u['id']);
 $grade=(int)($_GET['grade_level']??($section['grade_level']??($sections[0]['grade_level']??1)));
 if($grade<1||$grade>6)fail('Choose a grade from 1 to 6.');
 if($section&&(int)$section['grade_level']!==$grade)fail('Choose a section in the selected grade.');
 return [$grade,$sid];
}
