function level_cards(?array $assigned):void{
 /* The pupil's own level comes first with one big Continue button; skipped levels fold into "Optional practice"; locked levels are small. */
 $pid=(int)current_user()['id'];$start=(int)($assigned['id']??0);$next=next_learning_lesson($pid);$nextLevel=(int)($next['level_id']??0);echo '<section class="level-catalog" aria-label="BULIG levels"><div class="section-heading"><div><span class="eyebrow">ONE LESSON AT A TIME</span><h2>Your learning adventures</h2></div><p>Starting level: <strong>'.e(level_label($start)).'</strong></p><a class="btn secondary off-pagelink" href="?page=offline">'.icon('download').'Offline lessons</a></div>';
 $feat='';$other='';$skip='';$locked='';$skipIds=[];
 $pct=[];foreach(rows('SELECT * FROM bulig_levels ORDER BY id') as $l){
  $id=(int)$l['id'];$available=level_available($pid,$id);$skipped=$start>0&&$id<$start;
  $counts=one('SELECT COUNT(*) total,COUNT(p.completed_at) done FROM lessons l JOIN modules m ON m.id=l.module_id LEFT JOIN pupil_progress p ON p.lesson_id=l.id AND p.pupil_id=? WHERE m.level_id=? AND l.published=1'.GRADE_SQL,[$pid,$id,pupil_grade($pid)]);$count=(int)$counts['total'];$complete=$count>0&&(int)$counts['done']===$count;
  $ready=(bool)$l['published']&&$count>0;$label=$complete?'Completed':($skipped?'Skipped · optional practice':($start===$id?'Your starting level':''));
  $unavailable=in_array($id,[2,3,4,5,6,7,8],true)?'Content setup needed':($id>=4?'Coming soon':'Content unavailable');
  $pct[$id]=$count?(int)round(100*(int)$counts['done']/$count):0;$need=$nextLevel?:$start;
  $lock=!$available?' data-lock data-lock-title="'.e(level_label($id)).'"'.($ready&&$need&&$need<$id?' data-lock-need="'.e(level_label($need)).'" data-lock-href="?page=lessons&amp;level='.$need.'#level'.$need.'-path" data-lock-pct="'.($pct[$need]??0).'"':' data-lock-soon="1"'):'';
  $cur=$available&&!$complete&&$id===$nextLevel;$html='<article data-level="'.$id.'" class="level-card '.($available?'available':'unavailable').' level-tone-'.$id.($cur?' pf-current level-feature':'').'"'.(!$available?' data-pf-wiggle':'').$lock.'>'.($complete?'<span class="pf-stamp">DONE</span>':'').'<div class="level-cover has-cover cover-'.$id.'"><span class="level-number">'.e(str_replace('Level ','',level_label($id))).'</span><span class="cover-symbol">'.icon($available?($complete?'check':'book'):'lock').'</span><span class="cover-caption">'.($skipped?'REVISIT WHENEVER YOU LIKE':($available?'LET’S EXPLORE TOGETHER':'YOUR LEARNING JOURNEY')).'</span></div><div class="level-card-content"><div class="level-card-heading"><h3>'.e(level_label($id)).'</h3>'.($label?'<span class="status">'.e($label).'</span>':'').($cur?pf_ring((int)round((int)$counts['done']/max(1,$count)*100)):'').'</div><p>'.e($ready?$l['title']:$unavailable).'</p><small>'.($ready?lesson_count_label($id,$count).($skipped?' · Not required for your current level':''):(in_array($id,[2,3,4,5,6,7,8],true)?'Ask your teacher to finish installing this level.':'Activities are being prepared')).'</small>'.($available?'<a class="btn primary" href="?page=lessons&amp;level='.$id.'#level'.$id.'-path">'.($complete?'Review lessons':($skipped?'Explore skipped level':'Open lessons')).' '.icon('arrow').'</a>':'<span class="level-lock">'.icon('lock').(!$ready?$unavailable:'Finish the earlier required level first').'</span>').($available&&$ready?'<div class="off-slot" data-off-level="'.$id.'" data-off-title="'.e(level_label($id)).'"></div>':'').'</div></article>';
  if($cur&&$next){
   $html=preg_replace('~<span class="status">[^<]*</span>~','',$html,1);$html=str_replace('<h3>'.e(level_label($id)).'</h3>','<h3>'.e(level_label($id)).'</h3><span class="status">YOUR LEVEL</span>',$html);
   $html=str_replace('<a class="btn primary" href="?page=lessons&amp;level='.$id.'#level'.$id.'-path">Open lessons '.icon('arrow').'</a>','<p class="lf-next">'.(int)$counts['done'].' of '.$count.' done · Next: <strong>'.e($next['subtitle']?:$next['title']).'</strong></p><a class="btn primary lf-go" href="?page=lesson&amp;id='.(int)$next['id'].'" data-title="'.e($next['subtitle']?:$next['title']).'">Continue learning '.icon('arrow').'</a><a class="lf-path" href="?page=lessons&amp;level='.$id.'#level'.$id.'-path">See my learning path</a>',$html);
  }
  if($cur)$feat.=$html;elseif(!$available)$locked.=$html;elseif($skipped){$skip.=$html;$skipIds[]=$id;}else $other.=$html;
 }
 if($feat)echo '<div class="level-feature-wrap">'.$feat.'</div>';
 if($other)echo ($feat?'<h3 class="level-group-title">More levels</h3>':'').'<div class="level-card-grid">'.$other.'</div>';
 if($skip){$thumbs='';foreach(array_slice($skipIds,0,5) as $k)$thumbs.='<span class="ft ft-'.$k.'"></span>';
  echo '<details class="level-fold"'.(!$feat&&!$other?' open':'').'><summary><span class="ft-row" aria-hidden="true">'.$thumbs.'</span><span class="lf-txt"><strong>Optional practice</strong><small>'.e(level_label($skipIds[0])).($skipIds[0]!==end($skipIds)?' to '.e(level_label(end($skipIds))):'').' · skipped by your teacher. Open any of them to practise.</small></span><span class="lf-chev" aria-hidden="true">'.icon('arrow').'</span></summary><div class="level-card-grid">'.$skip.'</div></details>';}
 if($locked)echo '<h3 class="level-group-title">Coming next</h3><div class="level-card-grid level-locked-grid">'.$locked.'</div>';
 echo '</section>';
}

