function render_activity_visuals(array $a):void{
 $imgs=activity_images($a);$reviewed=level1_visual_override($a);$alts=$reviewed?array_column($reviewed['images'],'alt','src'):[];$expected=$reviewed!==null?[]:(visual_manifest()[(string)$a['id']]??[]);
 if(!$imgs){
  if(!empty($expected['external_picture']))echo '<div class="visual-notice" role="note">Use the picture of '.e($expected['external_picture']).' provided by your teacher for this question.</div>';
  elseif(!empty($expected['images']))echo '<div class="visual-notice" role="alert">This activity’s picture has not been set up yet. Please ask your teacher to report activity '.$a['id'].'.</div>';
  return;
 }
 echo '<div class="visual-gallery '.(count($imgs)>1?'multiple':'').'">';
 foreach($imgs as $img){$path=resolved_image_path($img);
  if(!$path){echo '<div class="visual-notice" role="alert">This picture is unavailable. Please tell your teacher: activity '.$a['id'].'.</div>';continue;}
  echo '<figure class="activity-visual"><a href="'.e($path).'" target="_blank" rel="noopener"><img src="'.e($path).'" alt="'.e($alts[$img]??('Module picture for '.$a['title'])).'" loading="eager" data-activity-image="'.$a['id'].'"></a><figcaption class="image-load-error" hidden>This picture could not load. Please tell your teacher: activity '.$a['id'].'.</figcaption></figure>';
 }echo '</div><p class="image-hint">Tap a picture to see it larger.</p>';
}
function visual_audit_view():void{
 require_role('admin');$manifest=visual_manifest();$issues=[];$count=0;$pictures=0;
 foreach(rows('SELECT * FROM activities ORDER BY lesson_id,id') as $a){$count++;$imgs=activity_images($a);$m=$manifest[(string)$a['id']]??[];if(level1_visual_override($a)!==null)$m=['images'=>$imgs];
  if(!$imgs&&(!empty($m['images'])||!empty($m['external_picture'])))$issues[]=['a'=>$a,'problem'=>!empty($m['external_picture'])?'Upload an approved picture of '.$m['external_picture'].'. The exact composition is not supplied in the PDF.':'No picture assigned. Apply 004_visuals.sql; edited activities must be checked in Lesson Studio.','path'=>null];
  foreach($imgs as $img){$pictures++;$resolved=resolved_image_path($img);if(!$resolved||$resolved!==$img)$issues[]=['a'=>$a,'problem'=>$resolved?'Lesson-folder file missing; original module copy is being used. Upload the complete assets folder.':'File missing or unreadable on this server. Upload it to the assets folder beside public/index.php.','path'=>$img];}
 }
 echo '<div class="pageheading"><div><h1>Activity image check</h1><p>'.$count.' activities checked · '.$pictures.' image references · '.count($issues).' items need attention.</p><p>This checks the database and files on the server running BULIG.</p></div></div>';
 if(!$manifest)echo '<div class="visual-notice">Upload database/visual-manifest.json for the complete assignment check.</div>';
 foreach($issues as $i){$a=$i['a'];echo '<section class="card"><h2>Lesson '.$a['lesson_id'].' · Activity '.$a['id'].' · '.e($a['title']).'</h2><p>'.e($i['problem']).'</p>'.($i['path']?'<p class="preserve">'.e($i['path']).'</p>':'').'<p>'.e($a['prompt']).'</p><a class="btn secondary" href="?page=edit_activity&id='.$a['id'].'">Edit activity pictures</a></section>';}
 echo '<section class="card"><h2>Verify browser loading</h2><p>Open a lesson below to test every assigned picture in your browser. This also detects HTTP errors that a filesystem check cannot detect.</p><nav class="lesson-tabs">';for($n=1;$n<=12;$n++)echo '<a href="?page=visual_audit&lesson='.$n.'">'.$n.'</a>';echo '</nav></section>';
 $lid=(int)($_GET['lesson']??0);if($lid>=1&&$lid<=12){echo '<div class="image-audit-results" role="status">Loading pictures…</div>';foreach(rows('SELECT * FROM activities WHERE lesson_id=? ORDER BY id',[$lid]) as $a){if(!activity_images($a))continue;echo '<section class="card"><h2>Activity '.$a['id'].' · '.e($a['title']).'</h2>';render_activity_visuals($a);echo '</section>';}}
}

function identity_banner(array $u,string $page):void{
 if($u['role']==='admin'||($u['role']==='pupil'&&in_array($page,['profile','settings'],true)))return;
 $home=$page==='dashboard'&&$u['role']!=='pupil';$h=(int)date('G');$sky=$page==='dashboard'&&$u['role']==='pupil'?($h>=5&&$h<12?'m':($h>=12&&$h<17?'a':'e')):'';$detail=ucfirst($u['role']);
 if($u['role']==='pupil'){$p=one('SELECT grade_level,section FROM pupils WHERE user_id=?',[$u['id']]);$detail=$p?'Grade '.$p['grade_level'].' · '.$p['section']:'Pupil';}
 elseif($u['role']==='teacher'){$sections=teacher_sections((int)$u['id']);$names=array_map(fn($s)=>'Grade '.$s['grade_level'].' · '.$s['name'],array_slice($sections,0,2));$detail=$names?implode(' / ',$names).(count($sections)>2?' + '.(count($sections)-2).' more':''):'Teacher · Your classroom';}
 else $detail='Administrator · BULIG school workspace';
 echo '<section class="identity-banner '.($home?'identity-home'.($u['role']!=='pupil'?' identity-staff':''):'identity-compact'.($sky?' kid-sky sky-'.$sky:'')).'" aria-label="Your profile">'.($sky?'<span class="ksky" aria-hidden="true"><i class="ks-sun"></i><i class="ks-c ks-c1"></i><i class="ks-c ks-c2"></i><i class="ks-st"></i><i class="ks-st ks-st2"></i><i class="ks-st ks-st3"></i></span>':'').'<a class="identity-photo" href="?page=profile" aria-label="View or change your profile picture">'.avatar($u).'<span class="photo-edit">'.icon('edit').'</span></a><div class="identity-copy"><span class="eyebrow">'.($sky?['m'=>'GOOD MORNING','a'=>'GOOD AFTERNOON','e'=>'GOOD EVENING'][$sky]:($home?'WELCOME BACK':'YOUR BULIG SPACE')).'</span><'.($home?'h1':'h2').'>'.($home?'Hi, ':'').e($u['name']).($home?'!':'').'</'.($home?'h1':'h2').'><p class="identity-section">'.e($detail).'</p>'.($sky?'<p class="identity-message">'.e([ 'm'=>'Ready to read, ','a'=>'One more story, ','e'=>'A bedtime story, '][$sky].explode(' ',trim($u['name']))[0].'?').'</p>':'').'</div>'.($home&&$u['role']==='pupil'?pf_sky():($home&&$u['role']==='teacher'?tf_sky():'')).'</section>';
}
