 if($next)echo '<span class="pfx-xp" data-pfx-xp="'.$pid.'" data-xp="'.(int)$s['xp'].'"><progress data-pf-fill value="'.(int)$s['xp'].'" max="'.(int)$next['required_xp'].'" aria-label="XP toward your next reward"></progress><span class="pfx-shine" aria-hidden="true"></span></span><span class="stat-foot">'.(int)$s['xp'].' / '.(int)$next['required_xp'].' XP · '.e($next['title']).'</span>';
 else echo '<span class="stat-foot">Every little effort counts.</span>';
