if(!function_exists('pf_streak_calendar')){
function pf_streak_calendar(int $pid,array $s):string{
 $since=date('Y-m-d',strtotime('-400 days'));
 $learn=array_map(fn($d)=>substr((string)$d,0,10),array_column(rows('SELECT day FROM learning_days WHERE pupil_id=? AND day>=? ORDER BY day',[$pid,$since]),'day'));
 $sign=array_map(fn($d)=>substr((string)$d,0,10),array_column(rows("SELECT DISTINCT DATE(created_at) d FROM audit_log WHERE actor_id=? AND action='login' AND created_at>=?",[$pid,$since.' 00:00:00']),'d'));
 $first=min(array_merge([date('Y-m-d')],$learn,$sign,[(string)(val('SELECT MIN(day) FROM learning_days WHERE pupil_id=?',[$pid])?:date('Y-m-d'))]));$cur=(int)$s['current_streak'];$best=max($cur,(int)($s['longest_streak']??0));
 $title=$cur>1?$cur.' days in a row!':($cur===1?'1 day. Keep it going!':'Start a new streak today!');
 $flame='<svg viewBox="0 0 24 30" class="pf-cal-flame" aria-hidden="true"><path d="M12 1c3 7-6 7-3 13 1-1 2-2 2-4 6 4 6 15-1 15S1 21 6 14c0 3 2 4 3 4-2-5 3-8 3-17z" fill="url(#pf-fo)"/><path d="M12 16c1 3-2 4-1 6l1-1c3 2 2 7-1 7s-4-3-2-6c0 1 1 1 1 1-1-2 2-4 2-7z" fill="url(#pf-fi)"/></svg>';
 return '<div class="pf-cal-ov" data-pf-cal hidden data-learn="'.e(json_encode($learn)).'" data-sign="'.e(json_encode($sign)).'" data-today="'.date('Y-m-d').'" data-first="'.e(substr($first,0,7)).'" role="dialog" aria-modal="true" aria-labelledby="pf-cal-title"><div class="pf-cal-panel"><div class="pf-cal-top"><button type="button" class="pw-close" data-pf-cal-close aria-label="Close">'.icon('close').'</button><div class="pf-cal-head">'.$flame.'<div><span class="pf-cal-eb">MY LEARNING STREAK</span><h2 id="pf-cal-title">'.e($title).'</h2></div></div><div class="pf-cal-sum"><div><b>'.$cur.'</b><small>Current streak</small></div><div><b>'.$best.'</b><small>Best streak</small></div><div><b data-pf-cal-count>0</b><small data-pf-cal-countlabel>Days learned this month</small></div></div></div><div class="pf-cal-body"><div class="pf-cal-mon"><button type="button" data-pf-cal-prev aria-label="Previous month">'.icon('arrow','pf-flip').'</button><strong data-pf-cal-month aria-live="polite"></strong><button type="button" data-pf-cal-next aria-label="Next month">'.icon('arrow').'</button></div><div class="pf-cal-wk" aria-hidden="true"><span>Sun</span><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span></div><div class="pf-cal-grid" data-pf-cal-grid role="grid"></div><div class="pf-cal-leg"><span><i class="pf-lg-learn"></i>Learned (did an activity)</span><span><i class="pf-lg-sign"></i>Signed in only</span><span><i class="pf-lg-today"></i>Today</span></div><p class="pf-cal-tip">Do one activity every day to keep your flame growing!</p></div></div></div>';
}
}
